import java.io.*;
import java.util.*;

public class E {
    public static void main(String[] args) throws Exception {
        new E().execute();
    }

    public void execute() throws Exception {
        Scanner scanner = new Scanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int l = scanner.nextInt();
        int r = scanner.nextInt();

        if (n % 2 == 1 && m % 2 == 1) {
            long result = power(power(r - l + 1, n), m);
            writer.println(result);
            writer.flush();
            return;
        }

        int evenCount = r / 2 - (l + 1) / 2 + 1;
        int oddCount = (r - l + 1) - evenCount;

        long[][] matrix = {{evenCount, oddCount}, {oddCount, evenCount}};
        matrix = matrixPower(matrix, n);
        matrix = matrixPower(matrix, m);
        writer.println(matrix[0][0]);
        writer.flush();
    }

    private final int MOD = 998244353;

    private long[][] multiplyMatrices(long[][] a, long[][] b) {
        int rowsA = a.length, colsA = a[0].length;
        int rowsB = b.length, colsB = b[0].length;
        long[][] result = new long[rowsA][colsB];

        for (int i = 0; i < rowsA; i++) {
            for (int j = 0; j < colsB; j++) {
                long sum = 0;
                for (int k = 0; k < colsA; k++) {
                    sum += a[i][k] * b[k][j];
                }
                result[i][j] = sum % MOD;
            }
        }
        return result;
    }

    private long[][] matrixPower(long[][] base, int exponent) {
        if (exponent == 1) return base;
        long[][] half = matrixPower(base, exponent / 2);
        long[][] result = multiplyMatrices(half, half);
        if (exponent % 2 == 1) {
            result = multiplyMatrices(result, base);
        }
        return result;
    }

    private long power(long base, int exponent) {
        if (exponent == 0) return 1;
        long half = power(base, exponent / 2);
        long result = (half * half) % MOD;
        if (exponent % 2 == 1) {
            result = (result * base) % MOD;
        }
        return result;
    }
}
